public int findLargestSubstring(List<String> strings) {
    int len = strings.size();
    if (len == 0) {
        return 0;
    }

    // Create a Trie node
    TrieNode root = new TrieNode();

    // Build the Trie with the given strings
    for (String str : strings) {
        buildTrie(root, str);
    }

    // Search for the longest valid substring
    String longestSubstring = "";
    for (String str : strings) {
        if (searchTrie(root, str)) {
            if (str.length() > longestSubstring.length()) {
                longestSubstring = str;
            }
            reverseAndSearchTrie(root, str);
            if (str.length() > longestSubstring.length()) {
                longestSubstring = str;
            }
        }
    }

    return longestSubstring.length();
}

// TrieNode class for node structure in Trie
class TrieNode {
    TrieNode[] children;
    boolean isEndOfWord;

    public TrieNode() {
        children = new TrieNode[26];
        isEndOfWord = false;
    }
}

// Helper function to build the Trie
private void buildTrie(TrieNode root, String str) {
    TrieNode current = root;
    for (char c : str.toCharArray()) {
        int index = c - 'a';
        if (current.children[index] == null) {
            current.children[index] = new TrieNode();
        }
        current = current.children[index];
    }
    current.isEndOfWord = true;
}

// Helper function to search for the maximum length substring
private boolean searchTrie(TrieNode root, String str) {
    TrieNode current = root;
    for (char c : str.toCharArray()) {
        int index = c - 'a';
        if (current.children[index] == null) {
            return false;
        }
        current = current.children[index];
        if (current.isEndOfWord) {
            return true;
        }
    }
    return false;
}

// Helper function to reverse and search for the substring
private void reverseAndSearchTrie(TrieNode root, String str) {
    TrieNode current = root;
    Stack<Character> stack = new Stack<>();
    for (char c : str.toCharArray()) {
        int index = c - 'a';
        if (current.children[index] == null) {
            return;
        }
        current = current.children[index];
        stack.push(c);
    }

    StringBuilder reversedStr = new StringBuilder();
    while (!stack.isEmpty()) {
        reversedStr.append(stack.pop());
    }

    current = root;
    for (char c : reversedStr.toString().toCharArray()) {
        int index = c - 'a';
        if (current.children[index] == null) {
            return;
        }
        current = current.children[index];
        if (current.isEndOfWord) {
            return true;
        }
    }
}
