public int findLargestSubstring(List<String> strings) {
    String longestSubstring = "";
    for (String string : strings) {
        for (int i = 0; i < string.length(); i++) {
            for (int j = i + 1; j <= string.length(); j++) {
                String sub = string.substring(i, j);
                String invertedSub = new StringBuffer(sub).reverse().toString();
                if (strings.contains(sub) || strings.contains(invertedSub)) {
                    if (sub.length() > longestSubstring.length()) {
                        longestSubstring = sub;
                    }
                }
            }
        }
    }
    return longestSubstring.isEmpty() ? 0 : Long.toString(Long.parseLong(longestSubstring) - 1).length();
}
