import java.util.List;

public class StringMatcher {

    public static int findLargestSubstring(List<String> strings) {
        String result = "";
        for (String str : strings) {
            if (isPalindrome(str)) {
                result = str;
            } else {
                int length = longestPalindromeSubstr(str);
                if (length > result.length()) {
                    result = str.substring(0, length);
                }
            }
        }
        return result.length();
    }

    private static boolean isPalindrome(String str) {
        int left = 0;
        int right = str.length() - 1;
        while (left < right) {
            if (str.charAt(left) != str.charAt(right)) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }

    private static int longestPalindromeSubstr(String str) {
        int len = str.length();
        boolean[][] dp = new boolean[len][len];
        int start = 0;
        int maxLength = 1;

        for (int i = 0; i < len; i++) {
            dp[i][i] = true;
        }

        for (int end = 2; end <= len; end++) {
            for (int start = 0; start < len - end + 1; start++) {
                if (str.charAt(start) == str.charAt(end - 1) && (end - start <= 2 || dp[start + 1][end - 2])) {
                    dp[start][end - 1] = true;
                    if (end - start + 1 > maxLength) {
                        maxLength = end - start + 1;
                        start = 0;
                    }
                }
            }
        }

        return maxLength;
    }
}
