import java.util.HashSet;
import java.util.Set;

public class OilDeposits {

    public static int countOilDeposits(char[][] grid) {
        int count = 0;
        int rows = grid.length;
        int cols = grid[0].length;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '@') {
                    if (isOilDeposited(grid, i, j, rows, cols, new HashSet<>())) {
                        count++;
                    }
                }
            }
        }

        return count;
    }

    private static boolean isOilDeposited(char[][] grid, int x, int y, int rows, int cols, Set<String> visited) {
        if (x < 0 || x >= rows || y < 0 || y >= cols || grid[x][y] != '@' || visited.contains(x + "_" + y)) {
            return false;
        }

        visited.add(x + "_" + y);
        return isOilDeposited(grid, x + 1, y, rows, cols, visited)
                && isOilDeposited(grid, x - 1, y, rows, cols, visited)
                && isOilDeposited(grid, x, y + 1, rows, cols, visited)
                && isOilDeposited(grid, x, y - 1, rows, cols, visited);
    }

    public static void main(String[] args) {
        char[][] grid1 = new char[][] {{'*'}};
        System.out.println(countOilDeposits(grid1)); // Output: 0

        char[][] grid2 = new char[][] {{'*', '@', '*', '@', '*'}, {'*', '*', '@', '*', '*'}, {'*', '@', '*', '@', '*'}};
        System.out.println(countOilDeposits(grid2)); // Output: 1

        char[][] grid3 = new char[][] {{'@', '@', '*', '*', '*', '*', '@', '*'}};
        System.out.println(countOilDeposits(grid3)); // Output: 2
    }
}
