public static int countOilDeposits(char[][] grid) {
    int n = grid.length;
    int m = grid[0].length;
    int[] direction = {0, 1, 0, -1, 1, -1, 1, -1}; // Up, Right, Down, Left, Up-Right, Up-Left, Down-Right, Down-Left
    boolean[][] visited = new boolean[n][m];

    int count = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                explore(i, j, grid, visited, direction);
                count++;
            }
        }
    }
    return count;
}

private static void explore(int x, int y, char[][] grid, boolean[][] visited, int[] direction) {
    int newX = x + direction[0];
    int newY = y + direction[1];
    if (isValid(newX, newY, grid.length, grid[0].length) && grid[newX][newY] == '@' && !visited[newX][newY]) {
        visited[newX][newY] = true;
        explore(newX, newY, grid, visited, direction);
    }
}

private static boolean isValid(int x, int y, int n, int m) {
    return x >= 0 && x < n && y >= 0 && y < m;
}
