private static void dfs(char[][] grid, int row, int col, boolean[][] visited) {
    if (row < 0 || row >= grid.length || col < 0 || col >= grid[0].length || grid[row][col] == '*' || visited[row][col]) {
        return;
    }

    visited[row][col] = true;
    dfs(grid, row - 1, col, visited); // up
    dfs(grid, row + 1, col, visited); // down
    dfs(grid, row, col - 1, visited); // left
    dfs(grid, row, col + 1, visited); // right
}
