public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create a set to store all n-tersections
    Set<Integer> nTerritories = new HashSet<>();
    for (int i = 0; i < n; i++) {
        nTerritories.add(i);
    }

    // Function to check if two n-tersections are adjacent
    boolean isAdjacent(int a, int b) {
        for (int[] path : paths) {
            if (path[0] == a && path[1] == b || path[0] == b && path[1] == a) {
                return true;
            }
        }
        return false;
    }

    // Use breadth-first search to search for a path from start to end
    Queue<Integer> queue = new LinkedList<>();
    queue.add(start[0]);

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == end[0]) {
            return "can be travelled";
        }

        for (int nextTerritory : nTerritories) {
            if (!nTerritories.contains(nextTerritory) || isAdjacent(current, nextTerritory)) {
                continue;
            }
            queue.add(nextTerritory);
            nTerritories.remove(nextTerritory); // Avoid revisiting
        }
    }

    return "cannot be travelled";
}
