public boolean canArrange(int[] arr, int k) {
    int[] counts = new int[k]; // Count the occurrences of each number modulo k
    Arrays.fill(counts, 0);

    for (int num : arr) {
        counts[Math.floorMod(num, k)]++; // Increment the count for the remainder when divided by k
    }

    for (int c : counts) {
        if (c % 2 != 0 && counts[k - c] > 0) { // Ensure there's a pair for the complement if remainder is odd
            counts[c]++;
            counts[k - c]--;
        } else if (c % 2 != 0 && counts[c] == 0) { // If there's no complement for an odd remainder, return false
            return false;
        }
    }

    return true; // If all counts are even, it's possible to form the pairs
}
```

