public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    int[] count = new int[k];

    // Count the occurrences of each remainder when divided by k
    for (int num : arr) {
        count[num % k]++;
    }

    int oddCount = 0;
    int evenCount = 0;

    // Calculate the odd and even occurrences
    for (int i = 0; i < k; i++) {
        if (count[i] % 2 != 0) {
            oddCount++;
        } else {
            evenCount++;
        }
    }

    // Check the conditions for partitioning the array
    if (n % 2 != 0) {
        // If there is an odd number of elements, one element must be left out
        return ceil(oddCount / 2.0) == evenCount;
    } else {
        // If there are an even number of elements, the number of elements of each remainder modulo k must not exceed the half of the length of the array
        return oddCount % 2 == 0;
    }
}
