        Graph graph = new Graph(n, edges, Arrays.asList(0));
        return dfs(graph, 0, -1, hasApple);
    }

    private int dfs(Graph graph, int current, int parent, boolean[] hasApple) {
        int time = 0;
        for (int child : graph.get(current)) {
            if (child == parent) {
                continue;
            }
            int childTime = dfs(graph, child, current, hasApple);
            if (childTime > 0 || hasApple[child]) {
                    time += childTime + 2;
            }
        }
        return time;
    }
}
