class Solution {
    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        // Create a graph representation
        UnionFind graph = new UnionFind(n);

        // Build the graph using the edges
        for (int[] edge : edges) {
            graph.union(edge[0], edge[1]);
        }

        // Helper function to calculate min time for the subtree
        int[] time = new int[n];
        for (int i = 0; i < n; i++) {
            if (i != 0 && !graph.isConnected(0, i)) {
                time[i] = Integer.MAX_VALUE;
            }
        }

        // Calculate the minimum time starting from node 0
        calculateTime(graph, time, 0, hasApple);

        // The result is the minimum time from node 0 to itself (1 edge)
        return time[0] + 1;
    }

    private void calculateTime(UnionFind graph, int[] time, int node, boolean[] hasApple) {
        for (int neighbor : graph.getNeighbors(node)) {
            if (neighbor !=	graph.find(node)) {
                calculateTime(graph, time, neighbor, hasApple);
            }
            if (hasApple[neighbor]) {
                time[node] = Math.min(time[node], time[neighbor] + 1 + (neighbor != 0));
            }
        }
    }
}
