private int dfs(int node, List<List<Integer>> graph, boolean[] hasApple, boolean[] visited, int time) {
    visited[node] = true;
    int currentCost = 0;

    for (int neighbor : graph.get(node)) {
        if (!visited[neighbor]) {
            currentCost = Math.max(currentCost, dfs(neighbor, graph, hasApple, visited, time + 1));
        }
    }

    if (currentCost > 0 || hasApple[node]) {
        currentCost += time;
    }

    return currentCost;
}
