public String sortString(String s) {
    StringBuilder sb = new StringBuilder();
    String[] chars = s.split("");
    int[] frequency = new int[256];

    // Count the frequency of each character
    for (String c : chars) {
        frequency[c.charAt(0)]++;
    }

    int start = 0;
    int end = chars.length - 1;

    // Process characters in ascending order
    while (start <= end) {
        // Append the smallest character encountered so far
        for (int i = 0; i < 256; i++) {
            if (frequency[i] > 0) {
                sb.append((char) i);
                frequency[i]--;
                break;
            }
        }

        // Process the largest character encountered so far
        for (int i = 255; i >= 0; i--) {
            if (frequency[i] > 0) {
                sb.append((char) i);
                frequency[i]--;
                break;
            }
        }
    }

    return sb.toString();
}
