private boolean splitArray(int[] nums, int sum, double average, int index, int totalSum) {
    if (index == nums.length || totalSum >= sum) {
        return totalSum == sum;
    }
    return splitArray(nums, sum, average, index + 1, totalSum + nums[index])
        || splitArray(nums, sum, average, index + 1, totalSum);
