public boolean hasAllCodes(String s, int k) {
    int substringLength = (1 << k) - 1;
    boolean[] seen = new boolean[substringLength + 1];
    for (int i = 0; i <= s.length() - k; i++) {
        int substringStart = i;
        int substringEnd = i + k - 1;
        int substring = 0;
        for (int j = substringStart; j <= substringEnd; j++) {
            substring = (substring << 1) | (s.charAt(j) - '0');
        }
        if (!seen[substring]) {
            seen[substring] = true;
        }
        if (seen.length == substringLength) {
            return true;
        }
    }
    return false;
}
