public boolean hasAllCodes(String s, int k) {
    // A set to store all possible strings of length k
    Set<String> allKLengths = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        allKLengths.add(s.substring(i, i + k));
    }
    // Convert the set to an array and sort it
    String[] sortedArray = new String[allKLengths.size()];
    allKLengths.toArray(sortedArray);
    Arrays.sort(sortedArray);

    // Generate all possible substrings of length k and sort them
    Set<String> generatedSubstrings = new HashSet<>();
    String[] generatedArray = generatePossibleSubstrings(k);
    Arrays.sort(generatedArray);

    // Check if the generated substrings are a subset of the sorted set
    for (String substring : generatedArray) {
        if (!sortedArray.contains(substring)) {
            return false;
        }
    }
    return true;
}

// Generate all possible substrings of length k
private String[] generatePossibleSubstrings(int k) {
    String sorted = "01";
    String prev = "";
    while (prev.length() < k) {
        String current = "";
        for (int i = 0; i < sorted.length(); i++) {
            for (char c : sorted.toCharArray()) {
                if (c == sorted.charAt(i)) {
                    current += "0";
                } else {
                    current += "1";
                }
            }
            if (!current.equals(prev)) {
                sorted += c;
                prev = current;
            }
        }
    }
    return sorted.split("");
}
