import java.util.HashSet;
import java.util.Set;

public class FibonacciMinSum {
    public int findMinFibonacciNumbers(int k) {
        Set<Integer> fibs = new HashSet<>();
        fibs.add(0);
        fibs.add(1);

        while (true) {
            int latest = fibs.last();
            if (latest * 2 > k) break;
            fibs.add(latest * 2);
            if (latest * 3 > k) break;
            fibs.add(latest * 3);
        }

        int count = 0;
        while (k > 0) {
            if (fibs.contains(k)) {
                count++;
                k -= k;
            } else {
                int prev = findFibonacciBefore(k, fibs);
                count++;
                k -= prev;
            }
        }

        return count;
    }

    private int findFibonacciBefore(int k, Set<Integer> fibs) {
        for (int fib : fibs) {
            if (k - fib > 0) return fib;
        }
        return -1;
    }

    // Test cases
    public static void main(String[] args) {
        FibonacciMinSum solver = new FibonacciMinSum();

        // Test cases here
