import java.util.PriorityQueue;

public class Solution {
    public int findMinFibonacciNumbers(int k) {
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        pq.add(1);
        pq.add(2);

        int count = 0;
        while (k > 0) {
            int next = pq.poll();
            if (next <= k) {
                k -= next;
                count++;
            } else {
                pq.add(next - k);
            }
        }
        return count;
    }
}
```

