public int maxUniqueSplit(String s) {
    int maxLength = 0;

    // Try splitting the string from each character to the end
    for (int i = 0; i < s.length(); ++i) {
        Set<Character> seenChars = new HashSet<>();
        String currentSub = "";
        int count = 0;

        // Construct the current substring
        for (int j = i; j < s.length(); ++j) {
            currentSub += s.charAt(j);
            seenChars.add(s.charAt(j));

            if (seenChars.size() != currentSub.length()) {
                // If adding one more character makes the substring duplicate, stop splitting
                break;
            }

            count++;
        }

        maxLength = Math.max(maxLength, count);
    }

    return maxLength;
}
