        return 0;
    }
    int total = 0;
    for (int i = curr; i <= s.length(); i++) {
        String str = s.substring(curr, i);
        if (!used.contains(str)) {
            used.add(str);
            total = Math.max(total, 1 + breakString(s, used, i));
            used.remove(str);
