public String getSmallestString(int n, int k) {
    if (k == 1) {
        return "a";
    }

    StringBuilder sb = new StringBuilder();
    int_remaining_chars = n - 1;
    current_value = 1;

    while (true) {
        if (current_value + remaining_chars >= k) {
            sb.append((char) ('a' + k - 1));
            k = k - (current_value + remaining_chars - k);
            remaining_chars--;
        } else {
            sb.append((char) ('a' + current_value));
            k -= current_value;
            remaining_chars--;
            if (remaining_chars == 0) {
                break;
            }
        }

        current_value++;
    }

    return sb.reverse().toString();
}
