    char[] chars = new char[n];
    chars[n-1] = ((char)(k % 26 + 'a'));
    k /= 26;
    char last = chars[n-1];
    for (int i = n - 2; i >= 0; i--) {
        char newChar = ((char)((k % 26 + 'a') - 1 + 'a'));
        if (newChar < last) {
            chars[i] = newChar;
            last = chars[i];
        } else {
            digits += 1;
            while (newChar >= last) {
                last += 1;
            }
            chars[i] = last;
            last = chars[i];
            digits -= 1;
        }
        k /= 26;
        for (int j = 0; j < digits; j++) {
            chars[i] += 'a';
        }
    }
    return new String(chars);
