public static double calculateProbability(int n) {
    if (n <= 1) return 1.0; // If there are 0 or 1 passengers, the last passenger will always sit in their own seat

    double[][] dp = new double[n + 1][2];

    dp[1][0] = 1.0 / 2; // If there is 1 passenger, only one seat out of 2 can be taken, so probability is 1/2
    dp[1][1] = 1.0 / 2;

    for (int i = 2; i <= n; i++) {
        dp[i][0] = dp[i - 1][1] / 2; // If the last passenger picks up their own seat
        dp[i][1] = (dp[i - 1][0] + dp[i - 1][1]) / 2; // If the last passenger picks up a seat for someone else
    }

    // The last passenger is in their own seat with probability dp[n][0]
    return dp[n][0];
}
