        if (num == high) {
            steppingNumbers.add(num);
            return;
        }
        if (num < high) {
            steppingNumbersHelper(num + 1, high, steppingNumbers);
            steppingNumbersHelper(num - 1, high, steppingNumbers);
        }
    }
