public static int countDigitOne(int n) {
    if (n == 0)
        return 0;

    int result = 0;
    int power = 1;
    while (n > 0) {
        int digit = n % 10;
        int higher = n / 10;

        if (digit == 0) {
            result += higher * power;
        } else if (digit == 1) {
            result += higher * power + n - power + 1;
        } else {
            result += (higher + 1) * power;
        }

        n = higher;
        power *= 10;
    }

    return result;
}
