public int countDigitOne(int n) {
    return countDigitOneHelper(n);
}

private int countDigitOneHelper(int n) {
    if (n == 0) {
        return 0;
    }
    int count = 0;
    for (int digit = 0; digit <= 9; digit++) {
        if (digit == 1) {
            count += powerful(10, n) / 10;
        } else {
            int exponent = (int) Math.floor(Math.log10(n)) - (int) Math.floor(Math.log10(digit));
            count += powerful(digit, exponent) * digit;
        }
    }
    return count + 1;
}

private long powerful(long base, long exponent) {
    long total = 1;
    while (exponent > 0) {
        if (exponent % 2 == 1) {
            total *= base;
        }
        exponent /= 2;
        base *= base;
    }
    return total;
}
