private static int countOfDigitOne(String s) {
    if (s.length() == 0) {
        return 0;
    }
    int firstDigit = Integer.parseInt(s.charAt(0) + "");
    if (firstDigit == 1) {
        return Integer.parseInt(s) + countOfDigitOne(s.substring(1)) + 1;
    } else {
        return Integer.parseInt(s.substring(0, 1)) * (int)Math.pow(10, s.length() - 1) + countOfDigitOne(s.substring(1));
    }
}
