public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int maxLength = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                int length1 = extendLength(mat, i, j, 1); // Horizontal
                int length2 = extendLength(mat, i, j, 0); // Vertical
                int length3 = extendLengthAntiDiagonal(mat, i, j, 1); // Anti-diagonal
                int length4 = extendLengthAntiDiagonal(mat, i, j, -1); // Anti-diagonal

                maxLength = Math.max(maxLength, Math.max(length1, Math.max(length2, Math.max(length3, length4))));
            }
        }
    }

    return maxLength;
}

private static int extendLength(int[][] mat, int x, int y, int direction) {
    int len = 1;
    while (x + direction >= 0 && x + direction < mat.length && y + direction >= 0 && y + direction < mat[0].length && mat[x + direction][y + direction] == 1) {
        len++;
        x += direction;
        y += direction;
    }
    return len;
}

private static int extendLengthAntiDiagonal(int[][] mat, int x, int y, int direction) {
    int len = 1;
    while (x + direction >= 0 && x + direction < mat.length && y + direction >= 0 && y + direction < mat[0].length && mat[x + direction][y + direction] == 1) {
        len++;
        x += direction;
        y -= direction;
    }
    return len;
}
