public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    int[][][] dp = new int[m][n][4]; // 4 states for horizontal, vertical, diagonal, and anti-diagonal directions

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                dp[i][j][0] = dp[i][j][1] = dp[i][j][2] = dp[i][j][3] = 1; // Starting length of 1 for the current point

                // Check horizontally
                if (j > 0 && mat[i][j - 1] == 1) {
                    dp[i][j][0] = dp[i][j - 1][0] + 1;
                }

                // Check vertically
                if (i > 0 && mat[i - 1][j] == 1) {
                    dp[i][j][1] = dp[i - 1][j][1] + 1;
                }

                // Check diagonally (right-top)
                if (i > 0 && j > 0 && mat[i - 1][j - 1] == 1) {
                    dp[i][j][2] = dp[i - 1][j - 1][2] + 1;
                }

                // Check diagonally (left-bottom)
                if (i < m - 1 && j < n - 1 && mat[i + 1][j + 1] == 1) {
                    dp[i][j][3] = dp[i + 1][j + 1][3] + 1;
                }

                maxLength = Math.max(maxLength, Math.max(dp[i][j][0], Math.max(dp[i][j][1], Math.max(dp[i][j][2], dp[i][j][3]))));
            }
        }
    }

    return maxLength;
}
