public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int maxLength = 0;

    // Check for horizontal lines
    for (int row = 0; row < rows; row++) {
        int currentLength = 0;
        for (int col = 0; col < cols; col++) {
            if (mat[row][col] == 1) {
                currentLength++;
                maxLength = Math.max(maxLength, currentLength);
            } else {
                currentLength = 0;
            }
        }
    }

    // Check for vertical lines
    for (int col = 0; col < cols; col++) {
        int currentLength = 0;
        for (int row = 0; row < rows; row++) {
            if (mat[row][col] == 1) {
                currentLength++;
                maxLength = Math.max(maxLength, currentLength);
            } else {
                currentLength = 0;
            }
        }
    }

    // Check for diagonal lines
    for (int i = 0; i < rows; i++) {
        int currentLength = 0;
        for (int j = 0; j < cols; j++) {
            if (i == j && mat[i][j] == 1) {
                currentLength++;
                maxLength = Math.max(maxLength, currentLength);
            } else {
                currentLength = 0;
            }
        }
    }

    // Check for anti-diagonal lines
    for (int i = 0; i < rows; i++) {
        int j = cols - 1 - i;
        int currentLength = 0;
        for (int l = i; l < rows; l++) {
            if (j >= 0 && mat[l][j] == 1) {
                currentLength++;
                maxLength = Math.max(maxLength, currentLength);
            } else {
                currentLength = 0;
            }
            j--;
        }
    }

    return maxLength;
}
