public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int maxLength = 0;

    // Check each cell to see if it could be the starting point of a longest continuous line
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                maxLength = Math.max(maxLength, 
                    checkHorizontal(i, j, mat, rows)
                        + checkVertical(i, j, mat, cols)
                        + checkDiagonal(i, j, mat, rows, cols)
                        + checkAntiDiagonal(i, j, mat, rows, cols)
                        - 1); // Subtract 1 because重复计算
            }
        }
    }

    return maxLength;
}

private static int checkHorizontal(int i, int j, int[][] mat, int rows) {
    int maxLength = 1;
    while (i < rows && mat[i][j] == 1) {
        maxLength++;
        i++;
    }
    return maxLength;
}

private static int checkVertical(int i, int j, int[][] mat, int cols) {
    int maxLength = 1;
    while (j < cols && mat[i][j] == 1) {
        maxLength++;
        j++;
    }
    return maxLength;
}

private static int checkDiagonal(int i, int j, int[][] mat, int rows, int cols) {
    int maxLength = 1;
    while (i < rows && j < cols && mat[i][j] == 1) {
        maxLength++;
        i++;
        j++;
    }
    return maxLength;
}

private static int checkAntiDiagonal(int i, int j, int[][] mat, int rows, int cols) {
    int maxLength = 1;
    while (i < rows && j >= 0 && mat[i][j] == 1) {
        maxLength++;
        i++;
        j--;
    }
    return maxLength;
}
