private static void permute(int[] A, int index, HashSet<Integer> visited, int& count) {
    if (index == A.length) {
        count++;
    } else {
        for (int i = 0; i < A.length; i++) {
            if (!visited.contains(i)) {
                visited.add(i);
                swap(A, index, i);
                permute(A, index + 1, visited, count);
                swap(A, index, i);
                visited.remove(i);
            }
        }
    }
}

private static void swap(int[] A, int i, int j) {
    int temp = A[i];
    A[i] = A[j];
    A[j] = temp;
}
