        return A.length == 1 ? 1 : 0;
    }

    int[] count = new int[A.length];
    int[] visited = new int[A.length];
    int squares = 0;

    dfs(A, count, visited, squares, 0);

    return squares;
}

private static void dfs(int[] A, int[] count, int[] visited, int squares, int index) {
    if (index == A.length - 1) {
        squares++;
        return;
    }

    int sqrtSum = -1;
    for (int i = 0; i < A.length; i++) {
        if (visited[i]) continue;
        int sum = A[i] + A[index];
        sqrtSum = (int) Math.sqrt(sum);
        if (sqrtSum * sqrtSum == sum) {
            visited[i] = true;
            count[index] = count[index] + 1;
            dfs(A, count, visited, squares, index + 1);
            count[index] = count[index] - 1;
            visited[i] = false;
        }
    }
}
