private static int[] findLeftSmaller(int[] arr) {
    int n = arr.length;
    int[] leftSmaller = new int[n];
    Stack<Integer> stack = new Stack<>();
    for (int i = 0; i < n; i++) {
        while (!stack.isEmpty() && arr[stack.peek()] >= arr[i]) {
            stack.pop();
        }
        if (stack.isEmpty()) {
            leftSmaller[i] = -1;
        } else {
            leftSmaller[i] = stack.peek();
        }
        stack.push(i);
    }
    return leftSmaller;
}

private static int[] findRightSmaller(int[] arr) {
    int n = arr.length;
    int[] rightSmaller = new int[n];
    Stack<Integer> stack = new Stack<>();
    for (int i = n - 1; i >= 0; i--) {
        while (!stack.isEmpty() && arr[stack.peek()] >= arr[i]) {
            stack.pop();
        }
        if (stack.isEmpty()) {
            rightSmaller[i] = n;
        } else {
            rightSmaller[i] = stack.peek();
        }
        stack.push(i);
    }
    return rightSmaller;
}
