public static int findSmallestInteger(int n) {
    String numStr = String.valueOf(n);
    int[] digits = new int[numStr.length()];
    for (int i = 0; i < numStr.length(); i++) {
        digits[i] = Character.getNumericValue(numStr.charAt(i));
    }

    int index = numStr.length() - 1;
    while (index > 0 && digits[index] <= digits[index - 1]) {
        index--;
    }

    if (index == 0) {
        return -1; // Reversing digits would not create a larger integer
    }

    int targetPosition = index - 1;
    for (int i = numStr.length() - 1; i > targetPosition; i--) {
        if (digits[i] > digits[targetPosition]) {
            int temp = digits[i];
            digits[i] = digits[targetPosition];
            digits[targetPosition] = temp;
            break;
        }
    }

    for (int j = index, k = numStr.length() - 1; j < k; j++, k--) {
        int temp = digits[j];
        digits[j] = digits[k];
        digits[k] = temp;
    }

    return Integer.parseInt(String.join("", digits));
}
