    for (int i = digits.length - 1; i > 0; i--) {
        if (digits[i - 1] < digits[i]) {
            int temp = digits[i];
            digits[i] = digits[i - 1];
            digits[i - 1] = temp;

            // Sort the remaining digits to get the smallest arrangement
            Arrays.sort(digits, i, digits.length);

            return Integer.parseInt(new String(digits));
