public static int findSmallestInteger(int n) {
    // Convert the integer to an array of digits
    int[] digits = new int[10];
    while (n > 0) {
        digits[n % 10]++;
        n /= 10;
    }

    // Find the position to insert the smallest digit to get the smallest possible number
    int smallestPosition = -1;
    for (int i = 0; i < digits.length; i++) {
        if (digits[i] > 0) {
            smallestPosition = i;
            break;
        }
    }

    // If no position is found, it means the input integer is already sorted in ascending order, and no smallest integer can be formed
    if (smallestPosition == -1) return -1;

    // Find the smallest digit greater than the digit at the smallest position
    int smallestGreater = -1;
    for (int i = 0; i < digits.length; i++) {
        if (i != smallestPosition && digits[i] > digits[smallestPosition]) {
            smallestGreater = i;
            break;
        }
    }

    // Swap the smallest digit greater than the smallest position with the smallest digit at the smallest position
    int temp = digits[smallestPosition];
    digits[smallestPosition] = digits[smallestGreater];
    digits[smallestGreater] = temp;

    // Sort the digits from the smallest position to the end to get the smallest possible number
    Arrays.sort(digits, smallestPosition);

    // Construct the resulting integer
    int result = 0;
    for (int i = 0; i < digits.length; i++) {
        result = result * 10 + digits[i];
    }

    return result;
}
