public static int findSmallestInteger(int n) {
    for (int i = 9; i >= 2; i--) {
        if (hasDigit(i, n)) {
            int temp = extractDigit(i, n);
            int numWithReplacedDigit = n - temp + i * 10;
            if (numWithReplacedDigit > n) {
                return numWithReplacedDigit;
            }
        }
    }
    return -1;
}

// Method to check if a digit exists in the number
private static boolean hasDigit(int digit, int number) {
    while (number > 0) {
        if (number % 10 == digit) {
            return true;
        }
        number /= 10;
    }
    return false;
}

// Method to extract a digit from the number
private static int extractDigit(int digit, int number) {
    while (number > 0) {
        if (number % 10 == digit) {
            return number % 10;
        }
        number /= 10;
    }
    return 0;
}
