public class CenterSymmetricNumbers {
    public static List<String> centerSymmetricNumbers(int n) {
        List<String> centerSymmetricNumbers = new ArrayList<>();

        for (int i = 0; i < 514; i++) {
            if (isCenterSymmetric(i, n)) {
                centerSymmetricNumbers.add("" + i);
            }
        }

        return centerSymmetricNumbers;
    }

    private static boolean isCenterSymmetric(int num, int halfLength) {
        String numStr = String.valueOf(num);
        int len = numStr.length();

        if (len < halfLength * 2) {
            return false;
        }

        for (int i = 0; i < halfLength; i++) {
            if (numStr.charAt(i) != numStr.charAt(len - 1 - i)) {
                return false;
            }
        }

        // For even lengths, middle characters can be 0
        if (len % 2 == 0) {
            if (numStr.charAt(halfLength) != '0') {
                return false;
            }
        }

        return true;
    }
}
