    List<String> half = new ArrayList<>();
    for (int i = 0; i < 5; i++) {
        half.add(String.valueOf(i));
        half.add(String.valueOf(i + 5));
    }
    List<String> left = new ArrayList<>();
    for (int i = 0; i < 5; i++) {
        left.add(String.valueOf(i));
        left.add(String.valueOf(i * 5 + 1));
        left.add(String.valueOf(i * 5 + 4));
    }
    List<String> right = new ArrayList<>();
    for (int i = 0; i < 5; i++) {
        right.add(String.valueOf(i / 5 * 5));
        right.add(String.valueOf(i * 5));
        right.add(String.valueOf(i * 5 - 1));
    }

    for (int i = 0; i < half.size(); i++) {
        for (int j = 0; j < left.size(); j++) {
            String num = half.get(i) + left.get(j) + right.get(i);
            result.add(num);
        }
    }
    return result;
