private static final int[] PRIMES = {2, 3, 5};
private static final int[] UPDATES = {2, 3, 5};

private static final int[] dp = new int[n + 1];
private static int index = 0;

public static int findNthUglyNumber(int n) {
    if (n <= 0)
        return 0;

    while (true) {
        int candidate = dp[index] * PRIMES[index];
        if (index == 2) {
            dp[index] = candidate;
            index++;
        } else {
            for (int i = 3; i < PRIMES.length; i++) {
                if (candidate % PRIMES[i] == 0) {
                    insert(candidate);
                    dp[index] = candidate;
                    index++;
                    break;
                }
            }
        }

        if (index == n) {
            break;
        }
    }

    return dp[n];
}

private static void insert(int value) {
    int i = 0;
    while (i < index && dp[i] < value) {
        i++;
    }
    System.arraycopy(dp, i, dp, i + 1, index - i);
}
